-- Reshapes demo_seasons (0025) from "one row per (show, league type)" to one row per SHOW, with
-- no league type baked in. The Demo Season picker now asks two questions -- which show, then which
-- game type -- so any of the 3 researched seasons can be tried as any of the 3 league types (a 3x3
-- matrix from the same 3 rows), rather than one fixed pairing each. demo-season-builder.ts now
-- computes ownership/roster-size generically from a season's cast + however many fictional players
-- it has, for whichever league type the viewer picks, instead of reading a stored assignment.
--
-- Also adds photoUrl per castaway, missing from 0025: Survivor reuses the real photo files already
-- in public/photos/; the Traitors S4 cast uses verified Wikipedia/Commons photos (18 of 23 --  the
-- other 5 have no page photo, and fall back to initials same as any castaway with no photo url); the
-- Challenge cast has none at all -- several auto-matched Wikipedia searches for that season's more
-- international, lower-profile cast returned confidently WRONG people (a French politician, a
-- novelist, a wrestler sharing a first name), so instead of risking a real person's photo being
-- misattributed to someone else, that whole cast just falls back to initials.
--
-- This is a fresh reference table from the previous migration in the same feature, not real league
-- data, so it's simplest to drop and re-seed it wholesale rather than ALTER-ing column by column.

DROP TABLE IF EXISTS demo_seasons;

CREATE TABLE demo_seasons (
  id TEXT PRIMARY KEY,
  show_id TEXT NOT NULL,
  name TEXT NOT NULL,
  episode_count INTEGER NOT NULL,
  data JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

